) AS (
  VALUES 
    (509::BIGINT, 'Excelente profesor, los libros suyos son muy buenos para estudiar. Siempre escribe en la pizarra sin usar presentación, pero para mi gusto es mejor. Explica muy bien y está atento a ayudar tanto en clase como en consulta. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'cc34c1f392c2297abde6cbbbded4b9888931f5129c1fb67103b7e0d3d479e42b'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'En lo personal... Las clases son muy claras, se logra a aentender muy bien los conceptos, sin embargo siento que talvez sea muy matematico a veces en su teoria. Tiene un excelente material de apoyo y en consulta muy dispuesto a ayudar. El problema es que, para mi, califica muy duro y no es de ayudar'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'f1fb82743bb4b28ec7bd2981dab8534d8463f80a44648c2e71f34c60a7e5a65e'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Es un profe bastante bueno. Las explicaciones siempre son muy claras y se dedica a hacer ejemplo de cada cosa. Solamente escribe en pizarra, no trae presentación, en lo personal me gusta así. Los quices son difíciles, pero en el examen califica justo (hasta suave).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2026-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'acdece0d0041c38429dca91d0d1c7a55e18272f913769217a135f13ef01dae1b'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, '100% recomendable el profe. Muy bueno. No dude matricular con el. Los quices son un poco largos con cierta dificultad, pero si estudia lo saca.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-06T00:00:00+00:00'::TIMESTAMPTZ, '20b8444094f8e89afa089ca8783fd814f513156903e36aa9c553f9317c1365c7'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Hace los quices fáciles si usted lleva la materia al día (ejercicios muy parecidos a lo que vienen en la práctica de la escuela. Tiene mucha paciencia, es muy comprensivo y se nota que le gusta mucho enseñar.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'c3e5244094abc1a61e161db1f0fb68479a25d8d3a41f81f21dc010e11b3924a2'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Un profe súper dulce y súper atento, muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'db94117c27657b3882d7966452f2963e3a7d3b309f28a56a330fcfaa75f97fc0'::TEXT, ARRAY[1687]::BIGINT[]),
    (509::BIGINT, 'Como profe y como persona es excelente, explica muy bien, si uno no entiende algo ya sea porque le cuesta o porque trae bases malas de cursos anteriores el con gusto le explica, no lo trata mal, si puede llevar con el, hagalo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'd79d6d324801dde8b39f26aafe2cebfba892b770a5e5d47d8b9cf7ef181b0d50'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Me vi el canal del proye de youtube y sinceramente gracias a que vi sus clases pude pasar calculo superior el cual lo estaba llevando con otro profesor. Hubiera sido bueno poder llevar este curso con este profe es muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5dedbeff177cd5968109fcf1992fed3dd1a8ddee42eede1a3f3a589ad4adffa9'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica super bien, si tiene preguntas no dude en hacerlas, los quizzes son un poco duros pero si se prepara le va bien, en nuestro caso hizo tarea - quiz, las tareas son un poco duras por lo que no las deje para último momento. Si va a consulta lo ayuda mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'fbd47034981c41d1110918052f5212b8f8d860cac7b2e64495cf33132914565f'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'No esta mal, recomendado :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6e1a1975cef59c73cebef495ab00cb4391f9234582a11d3922820753d604479c'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Excelente profe. Califica duro pero ayuda muchísimo si uno va a consulta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '4a9527a24d506d1fcfd1ad2cd062923684a0801b4e4a34b6d3c52a53d40eb958'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Es bueno explicando, y bastante claro. Los exámenes cortos son de dos preguntas y son de las guías, pero hay que ir preparados. Es MUY importante ir a consulta. Y si el ve el interés, llega a ayudar mucho.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, '4b4bd48d3118314545d9ce6e315f900649bf864f359a69db0b53c15d335b0888'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor, se le entiende todo y se nota que le sabe y le apasiona la materia, hace que a uno le den ganas de ir a clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'c71cdb08ebc5f73162b702c0026e7ec108c00ddb462466bb9fb8babeb0f8181d'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (509::BIGINT, 'Él profe es muy buena gente y explica bien, tiene una voz tranquila pero no de las que aburre. Hace quizes constantemente entonces lo tiene a uno al día y no son difíciles. No califica duro la verdad, pero no perdona nada. Solo me gustaría que hiciera más ejemplos nivel examen pero todo bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8ee710d77805536b66de1739c851c55cde192dfeab3cd71f5baba829ed2b26a6'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'SI le falta poco para pasar el se toma la molesta de ir a buscarlo y ayudarle para que pueda pasar, no regala la nota pero si es un bien profe y entiende a los estudiantes. explica l materia excelente pero le recomendaría siempre estudiar exámenes viejos e ir al día con la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'eaea95533a1cdb05c1d3087ae4810793c174afe4bee927fd5d3924c4ce694f9b'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Explica muy bien pero los ejemplos de la clase pueden ser muy fáciles a comparación de los que da cátedra, entonces es importante ir al día con las guías de cátedra. Es muy accesible y busca ayudar al estudiante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9a5807c43d5c1ebd5958ebed478a83e265b9e6fc78a409b3907d0a8e8ffccb1a'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Explica bastante bien pero el único inconveniente está en que hace pocos ejemplos en clase y estos son muy sencillos en comparación con los de las guías y quices También hace quices casi que todas las semanas, lo que obliga a estar al día con la materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '417276eb044d276783d425df9d0b677948034a59f33e9d0f6c440556e74fc02b'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'El profesor explica súper claro y es muy agradable. El único inconveniente es que realiza quizzes muy seguido por lo que hay que llevar la materia al día, además que el nivel de estos están muy por encima comparado con ejercicios vistos en clase, por lo que hay que prepararse bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'cb0eda1b95159dd511daf80ec7dc637b1451ca857cda956c1b103537e1cf54a6'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Buen profe, hay quiz o tarea todas la semanas entonces hay que llevar la materia al día. Explica bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '8353b8293dc27ea08e3c3ea58df64c0921f3125986f53c6013fe042b8a6bff48'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'sus clases son aburridas , no ve 100% la materia en clase . Por lo tanto obligadamente tienes que estudiar más y ver ejemplos más difíciles tú solo (los que salen en el examen) Pero es muy humano y muy buena nota'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0d61a46e4ce31cf14b318f8f0054f75db7b885b2182d967271c30ba403b5e077'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (509::BIGINT, 'Ayuda mucho si usted pone de su parte, se hacen quices casi todas las semanas entonces se tiene que tener la materia al día. Valora el esfuerzo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '16ac5354a8048105f48c0c10789f16bc53c02480378b1c8b0caebbcd5af175c1'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Es muy buen profe, está muy dispuesto a ayudar pero si a que poner de su propia parte y practicar bastante para seguirle el ritmo al profe. Es muy organizado y amable.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '8f802251ddd06a293032119259653f847160d7e5935cae527340e70c4246d6d5'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'El profesor ayuda mucho si usted pregunta, gracias a eso no me quede en los cursos todas las veces que tuve una duda fui a consulta y si le preguntas 1 millón de veces la misma pregunta la responde hasta que entiendas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, '7252474ce15bbad59c4e78f4412768b88d791950290608d482f8b5005aabacb6'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Lo admiro demasiado! Nunca me dejó rendirme y siempre me ayudó a entender! Se aprende demasiado ... Excelente profesional y excelente profesor ! Explica bien y espacio... Califica duro pero vale la pena !'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '61f9d3f17c03e6d64970309370191ca4e7aa70ce388045c20293c66a1bb728e1'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '3c1a4159a62d9772cfd4bbd89173042d0d1150b1d31f240b371b9fe82134c169'::TEXT, ARRAY[563]::BIGINT[]),
    (509::BIGINT, 'Es un excelente profe, la consulta siempre esta disponible, es demasiado buena gente. Con respecto a las explicaciones son super claras, hace muchos ejercicios de examenes viejos, del folleto de el y de la catedra. Solo hace falta ir a clases para entender todo, yo nunca hice la consigna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '7db2e4a7c597a042e1146b4f5b6cc8932873a062d55012c434bbb2dfdb9ac6b8'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, '(VIRTUAL!!) Hace bastantes ejemplos y explica claro, pero tiene que repasar sí o sí porque los exámenes son más rudos que lo que se ve en clases. Los quizes son muy sencillos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'f8262a1636efaba159a8e1c008c79c587ddd337366bc29676a0ca8f09aa0efec'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica muy bien y sube las clases y los apuntes después de la clase. Lo único es que este semestre algunos temas que no profundizó solían venir en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '256eb95a2f84ce54d6dfe54806a36b8e537578f64ae8b7fc69494306b25071a4'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El profe es excelente, explica ejemplos que dejan la materia bien clara y las clases no son aburridas, se apegó muy bien a la virtualidad y sube todas las clases a youtube, además los quices son fáciles y deja todo un día para hacerlos, lastima que las evaluaciones de la cátedra no son lo mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '5edd8defa76a76857fc9a83b6f1bfb624dab6069ee4906d9551c0f2a483def9b'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Adaptación a la virtualidad excelente Se preocupa que el estudiante aprenda, fuera de clases ayuda bastante al realizarle consultas, las clases grabadas bien organizadas para fácil acceso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '7ba837f0819d2c6a8e79347bec4f499283b63141f6cdca41633c67bec2a41448'::TEXT, ARRAY[563]::BIGINT[]),
    (509::BIGINT, 'Muy buen profe. Explica bien, se preocupa por el estudiante, en modalidad virtual le va muy bien, sube los videos el mismo día y es muy claro, los quices son sencillos los hace por el GAAP y da 24hrs para hacerlos. Lo único sería que a veces hace pocos ejemplos o muy sencillos. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bdc39a7a44fe17aacd2944e537df0b486efcf3307507307b38fc5e356a7898d3'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El mejor profesor que he tenido hasta ahora, demasiado agradable'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'aa733b9c0d2c82265c1e9166ab4a1bcc9c9b306fb3b0aec3001f0b59ea8de61a'::TEXT, ARRAY[564]::BIGINT[]),
    (509::BIGINT, 'El profe es pura vida, explica muy claro y le interesa que los estudiantes aprendan de verdad. Se adaptó de forma excelente a la modalidad virtual y las clases son más cortas para mantener la concentración de los estudiantes, pero, es importante que los estudiantes hagan ejercicios por su cuenta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-29T00:00:00+00:00'::TIMESTAMPTZ, '3596f44bc8b4029d06a2c2701737f79d5708d97172de0f32078aec508db0e64f'::TEXT, ARRAY[564]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor, de los mejores de la cátedra y de matemática. Subía todos los videos rápido y sus clases fueron muy claras, solo quizás daban un poco de sueño. En general, aprendí mucho y la virtualidad no fue un impedimento para él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'c3a8f88bcdd2db9f986b5bdf4bcb1614c16d3673088e58d51ac2a16492046a74'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Con Borbón la cuestión es fácil: asistir a la clase, llevar la materia al día, evacuar dudas y sacar bien los quices (son pocos). El profe es bastante claro a la hora de explicar y las clases son muy provechosas. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'b41b929cc04cdaa9c1483e6ea70bba1d7b5fab27e6378565dba57897ec267bb9'::TEXT, ARRAY[563]::BIGINT[]),
    (509::BIGINT, 'Uno de los mejores profes del Tec, tiene sus clases planeadas, explica muy bien los ejercicios, después de como un momento para que uno piense y resuelva unos cuantos solos mientras el pasa por las filas por si hay dudas. En las consultas explica hasta que uno entienda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'f9460591178e44ac5cfd13957a113f83a74f7ce3394e6c27a16d4174be0bf27d'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'El profesor es muy buena persona, explica bien, se toma el tiempo para que entiendan los temas. Recomendado :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a7b413d0dc12df6024a4624dc6e30afd1e84185ae9cf107635a071d59917ef13'::TEXT, ARRAY[564]::BIGINT[]),
    (509::BIGINT, 'Sus clases son agradables, explica muy bien la materia y se asegura de que entienda bien todo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-12T00:00:00+00:00'::TIMESTAMPTZ, '55af28e4bf9a289ed172a1e14a2365735964376f114fc37ed38323604611eafc'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El profe es demasiado bueno, explica de maravilla y domina la materia. Siempre hace bastantes ejemplos, si puede meter con él, hágalo de una.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '4c1c33c9b80db8c4c930a7d8f244d8d6ed3dbd23532e9609851da1e9415238b0'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El mejor sin duda. Sobre todo en ese curso que hay profesores malísimos. Explica todo y solo se estudia del cuaderno. Si puede meta con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, '4cbc0ba008e8963737aad2cc469f89de8daed5c1e4e08891f3954752ed2e7d7b'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Te amo Borbón! Jaja este profe es demasiada calidad, da la materia súper clara. Por otra parte, sí, extiende la clase bastante pero cuando se llega al examen los ejercicios son del mismo tipo que se vio en clase. Llévelo sin miedo con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '3a68f8da734b53e3839dd6574e32e8d21c092254cd0976efb630009dc82e1e4d'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El profe es demasiado buena nota, en clase pone ejercicios para que uno haga y pasa revisando como uno va.... pero algo malo que tiene es que es demasiado aburrido, y usualmente demuestra todo y suele ser aburrido, en algunas clases casi todos dormidos pero él seguía... Califica suave, y es rápido..'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c7a0f0af3507455b8bae3b1cc772e521a587267dcfade3f75438703699e54a8b'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Síper buen profe. Explicá super bien, se detiene para que uno resuelva por su cuenta y en cualquier momento le puede preguntar algo con confianza. Super buena nota. Revisa normal, a veces ayuda. Meta sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-17T00:00:00+00:00'::TIMESTAMPTZ, '179be725572e5d734402312a394fd8dad8f34c695fc358a37928f5d3397d72ec'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9da70298c5352ab868a1cc31ddb789c2cd3c5ccd77b6cf82605514cc6856e4f6'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'El profe explica bien y califica justo, siempre da puntos por procedimiento. Tarda un poco en dar los quices pero es por los asistentes es bastante bueno la verdad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f52157dfdd7357271ff3b1dee3473541d96f77334e13289f82a16aae2d64ecc0'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Profesor sumamente aburrido, para nada dinámico. Las clases se hacen eternas. Explica con ejemplos super sencillos y los quices complicados'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9dc9216f46d9dd9adb3eb97945f22d435e9cb3a640f8e5e4f8253bbafda93850'::TEXT, ARRAY[564]::BIGINT[]),
    (509::BIGINT, 'Me atrevo a decir que es el mejor profe que he tenido en el TEC, siempre se preocupa por sus estudiantes y hay que llevarle el ritmo, lo que obliga a estudiar pero al final todo sale súper bien. Súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'bcece0092b22d229bb0c1c4fcd5998514089a6c827f5c341c772c24eb7a96a31'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Habla muy claro y las clases fluyen de manera constante, si uno se pierde le puede preguntar perfectamente bien y cada cierto tiempo hace pausas para que uno resuelva solo y el pasa por las filas revisando lo que uno hace, los asistentes revisan los quices bien brutal pero los examenes son faciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'b261b34e3f72534bb6739205e5e732fa0b18f440babc3a3cae7c6280f22a7b1c'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Deja guias semanales que se vuelven un poco tediosas pero sirven para estudiar. A las clases presenciales solo llega a hacer ejercicios para explicar lo que se supone que uno ya estudio. Quices virtuales y hablo demasiado bajo. Es mejor intentar llevar este curso presencial.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '3c6dca3c67a64bb80142ff021eb665e9a2ad7a4ecfc7747e5a1afd493e273198'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Es un exelente profesor. La materia la da muy clara y entendible. Comprende a los estudiantes y evalua como debe ser. No deja tareas y los quices son sencillos. Se preocupa por los estudiantes y está disponible en consulta. Además buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, '14e06de10097fb82fc5718acbdd2b577352f71fa3afc9396d8b135905a4b5197'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica EXCELENTE, da muchos ejemplos, es muy claro y siempre está dispuesto a explicar las veces que sean necesarias.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-26T00:00:00+00:00'::TIMESTAMPTZ, 'e933f894f1bfa5bff9e0a6c566e9e37a0a784431272e675f8c907fe4ca6a7ee2'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor. Hace varios quices que ayudan mucho para el examen. Explica demasiado bien y bastante claro, el único problema es que habla muy bajo, de ahí en fuera un excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3cb9b64ad481bfec1847ca17dd0a73e86ade349d161360e43cb89dc86dedb0b3'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El mejor profesor de matemáticas que he tenido. Se interesa en explicar de dónde salen las cosas y se le entiende super bien. Se aprende de verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'df228260da886d2d4d79a65268982b446127afad215f52a832fc69884ff269f2'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'En cursos semivirtuales deja muchas tareas pero ayudan mucho para estudiar, los quices son semivirtuales también y se contaba la participación en facebook. Atiende dudas de buena manera.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b2e079925e483d9e2d25c97fa89f1ae9c0ad44f014e93821b1cb0115cca8f541'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'El modo semivirtual con este profe promete. Responde rápido a las dudas por Facebook. Es bastante comprensivo y el curso es bastante pasable si se compromete a realizar las guías con tiempo. Pero por parte del profe excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c7a8c46d33dc02c8ec7cc934744694e7ef9aca3ed8113853f4b601c4e03992f8'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Califica normal. Es muy paciente y explica bien. Atiende cualquier duda, es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, '7e681f94ea73a79624ba6385d9f3e2836a18d04a9527928679866a56a66abc30'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Recomendado, habla muy bajo pero igual se le entiende. Hace ejemplos muy similares a los del examen y siempre al final de la clase da como un anuncio de lo que se va a ver en la siguiente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '094c4f435663003c5f0fe2b6a664f9f027d4b006c302871496807ffed8dfcec0'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Super recomendado! Los quices son fáciles, es claro explicando y tiene bastante paciencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f834ee0a0ae0b1d4285b785fe15d32356409f4327b127bf358dfbd4a5dd8c0df'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Muy buen profe, es claro y ordenado al explicar, y si hay alguna duda en consulta es muy paciente y si es necesario explica de nuevo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'e5ee34e43e50e1c1361d981b3ae6f46ab25e6e2a60bae4c3d4d80be88c5ba212'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Exelente profesor, hace bastantes ejemplos, explica muy claro, es muy paciente con el estudiante y no le moste explicar dos o mas veces, con solo ir a clases y hacer los ejercicios recomendados se pasa'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'c98e721b44ce46461e4ffdc894acaa444c7022621de9e1543baf38f77cf3046a'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Exc profesor se le entiende super claro, siempre atiende las dudas, 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '7bcbb7f6899d49a95049731f3f118fe59734cd81aafff324dd501319cbb9c107'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor. Si uno asiste siempre a clases y presta atención, el curso se pasa solo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e28f2c6e89ca7c1bb4fdfec06f03e196eb2a1b430195dc0277c64af79249b8ff'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Habla bajo, por lo demás es excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-09-05T00:00:00+00:00'::TIMESTAMPTZ, '8b6b7f60a77a45853bb4ce9108fc37a24dbd94162bdbc6bc6597a976fe9b1fe2'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'EXCELENTE profe para superior. Quices acordes a lo visto en clase, califica super justo (el/la asistente es mala nota calificando quices, pero el profe en los exámenes da puntos por casi cualquier intento). Tiene material buenísimo (folletos)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dbd77550a95e42ab1df343017d714ef01e70c3bc7e425bec1da8c68bcca2004e'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Este profesor está hecho para dar este curso, explica excelente lo malo dicen las malas lenguas son los quices'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5f38f3c8e8b2c2fb50100b39e55489407c31173c2b7d94ffe1c1911b71d91a72'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8d278a075d46a0dee90f0acd8501427d06074f9e5aecdd2b634e433ffea12d19'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (509::BIGINT, 'Habla muy bajito. Califica de regular a duro. Organiza bien la clase. Hace los quices necesarios, y sí hay que estudiar. Uno va al examen sabiendo, pero ocupa buscar ejercicios por aparte, los de la clase son muy fáciles. Busca ayudar en la comprensión, pero en la nota no regala nada'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd95747f5fe3714ff0a87399b3c66859c9830e2b7fc5f597d92b357d326a48f14'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Muy muy bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e48b788e0351b021e4311f2e7592fc32942d4216c961ba277df8f80a98c52490'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'él sabe bastante pero los ejercicios que da en clase sirven para entender la materia pero no para el examen porque son muy sencillos y habla muy bajo, califica un poco rudo a mi parecer pero no explica tan mal y atiende dudas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5f1a36bda1248708a684deebfcd79a6f505f5e9cf877c4e729c8c9d26f37d9bb'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'El profe es súper cute :3. Hace pocos quizes y no son tan imposibles; eso sí, califica un poco rudo. Distribuye bien las clases, a veces son poco rápidas, pero da muchos ejemplos y hace que uno practique en clase:) Y ama dar superior'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '7de26998a0a57cc4c3bf6e525209c3d77a2116a061e9dbd62de4f31dbb2a58db'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Es muy buen profe, explica la materia bastante bien, atiende las dudas, quices son normales/rudos y califica algo duro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'e982d23daaa7c7d63098f37d008dc534b4e0aba4b67adde67cc42ad0f4dde462'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Hace solo los quices necesarios, bastantes difíciles y no especifica bien que va a entrar en el quiz por lo que afecta al estudiante. Califica demasiado rudo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-05-24T00:00:00+00:00'::TIMESTAMPTZ, '5add759816688b7fbaef973e73c296fcdeaaaf1daf2ca3e50fb4782411c4a994'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Habla muy muy bajo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'fb857cd2667d244d9caf8a90008a0bc22ba94bd40f069e03fac870866305cca2'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Califica muuuy rudo a mi parecer. Pero se compensa porque explica bastante bien. Los quieces son a morir. Depende de su capacidad de entendimiento que logre pasar con él.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'b81970d11f6d916616319315126fc7731055f738791ab80da1fda302e2353e28'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Sabe demasiado y explica súper bien. Los quices son fáciles si usted puso atención en clases, casi que son los mismos ejercicios. Eso sí, califica un poco rudo y más en el primer examen por los dibujos y también habla bajito. Después de eso 100% recomendado :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-31T00:00:00+00:00'::TIMESTAMPTZ, '6f8634252f5e13b73a268fdfb4bbeb4c5b1c781adac59c5aebd654cc03c5e7dd'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Califica demasiado duro, pone mucha atención de detalles minimos, pretende que se hagan dibujos perfectos.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6b7bf09ae3e8304e038e4bef3b6e0ccfdfc9037a05afb1156ed4166717999e49'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Es un buen profe para superior, explica super claro y algunos quizes son fáciles otros dificiles, califica normal, pero eso si NUNCA hable en su clase porque lo ridiculiza delante de todo el aula ya que el habla muy bajito y le gusta escucharse. RECOMENDADO'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Clases excelentes']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '76fe8799534127a919c6df6fca84b835d62a64d90d70911b85dd4c12dbed3fbe'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6b9f0543e1ea46829f951ca801c0318f91dcd74b7bcd60643d825720b8336132'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor. Explica muy bien, y repite las veces necesarias. Los quices no son tan fáciles, pero nada del otro mundo tampoco. Recomendadísimo!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fdc3829c88c872adad85fe33d31223e8c76cbf316b908d30afe53a30840156e5'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica bien y Califica Suave, meta con el!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '9984e0a6b11c92b2d96faae449680db17630b8ca905621ec7eac81bc66106d47'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica demasiado bien y califica suave. Hace bastantes quices y no son tan faciles. Una excelente opcion para cualquier curso de mate. Lo recomiendo bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd62dc76813c7d161631f872821a631e6df30056cc1fb2f20c5084944a39e7304'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Excelente profe, explica super bien y se nota que sabe lo que hace. Los quices aveces son un poquillo rudos, pero nada que no se haya visto. Recomendado!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0f4c6347d4a334ac5998ecff5a071880390b10e4f397f7a01f4fa052b65a1ede'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Excelente profesor... La clase es muy entretenida y muestra mucho interes en que el estudiante aprenda... Dele sin miedo..'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-31T00:00:00+00:00'::TIMESTAMPTZ, '6b43b779c0bbc6eb471329ba17c06dab99bf4fe63e773c820337546de06f935b'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'bc7afb0cd623356669a6119b6b1e4f2e58a20fe2cb63d2a9ca9e54b72a7b1d06'::TEXT, ARRAY[923, 935]::BIGINT[]),
    (509::BIGINT, 'Sabe mucho más de lo necesario y está dispuesto a ayudar en todo. Se le entiende de todo en las clases y, sin esforzarse mucho, uno sale sabiendo reponder cualquier ejercicio del tema. Solo que es fácil olvidarlo por lo poco que cuesta aprender. Califica un poco duro pero uno aprende muy bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1472291314e60e1d32a67c1c16c61942029b190624d0d211daab66baf387e690'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'el mejor profesor de la escuela'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, '031df9907c4c2093c6e0d72ecd7baa8e16f5e6c1599503b4c6eea1f52f106d6d'::TEXT, ARRAY[935]::BIGINT[]),
    (509::BIGINT, 'simplemente el hombre sabe lo que hace CRACK'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '22d42664938b542a31162a7150458e2abd7ea0c1ee4fab15f4afb32ad2cb9673'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'crack'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'c5e6c70675afe1dfa698dc82756af31f97d1daa5eabe87e65fff5ac376ae2742'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Se preocupa por que el estudiante entienda, muchos ejemplos y califica normal. Y si hay que estudiar para los quices.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9b7a5487c8094e160df216f0d77866202105824065de2068b15d6b8239ec6ca1'::TEXT, ARRAY[605]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-01T00:00:00+00:00'::TIMESTAMPTZ, '0a7cba70b01e4d479dacb0d7ecc65b586ab4ee3114e05fc3cab2a1bea2bccee9'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Explica muy bien, hace muchos ejemplos casi que abarca todo tipo de ejercicio posible, si hay que estudiar para los quices, y calificando es normal en mi opinión, simplemente no regala nada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, '5953dc7a092aada08ebfd76b32bea7e125ad8154c7c0cd6fcfd52ad06d3b1835'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Es un excelente profesor. Explica muy bien la materia y utiliza muchos ejemplos. Atiende dudas en la clase y en consulta y es muy atento. El único problema es que califica duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'a7f73f04c9329c732007b1c2e8ebbf90c1456ff9f75b1bef8009221e87241c10'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Para mi, el no es buen profesor y no explica tan bien, los quices los hace dificiles y es estricto al calificar, no lo recomiendo para nada.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-18T00:00:00+00:00'::TIMESTAMPTZ, '297f02d5eb68f9c63d8c1df6b27a632bd71ffc4cfc8e70e393d15bbe34d40744'::TEXT, ARRAY[1018]::BIGINT[]),
    (509::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'deb5a45b5f338fb5fcff7fa442f4b48c216628f38a258d5cd3ed3ca80e691432'::TEXT, ARRAY[634]::BIGINT[]),
    (509::BIGINT, 'Explica demasiado bien, la materia se entiende con claridad en cada clase, se preocupa xq el estudiante entienda todo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'cdddbfd861d467f47dac04906fc5c1e4b0b8d0cf9caad0b49789d7cad028c5b2'::TEXT, ARRAY[935]::BIGINT[]),
    (509::BIGINT, 'Muchos ejemplos por tema, explica bastante bien, para los quices si se tiene que estudiar un poco pero tampoco la gran cosa, califica normal. En general excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b9ba747d98738e9b1ec2f9e7899db0f7e329b99d9ca9e050b77041eac71be39f'::TEXT, ARRAY[923]::BIGINT[]),
    (509::BIGINT, 'Las clases son un poco aburridas, pero deja la materia bastante clara.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f29f3c6e0a0a51830793272c47f4489772b205ca13f87ca06fd32b075f57c586'::TEXT, ARRAY[1018]::BIGINT[]),
    (509::BIGINT, 'Excelente manera de dar la Clase. Un excelente profesor, muy didáctico'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'dd81fc9ab8eaf11b3693c6ac56e003135bd8e7173b55f3f5d3c0623eda77a130'::TEXT, ARRAY[923]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
